// Oeste BlockLogoCloud — Topanga block (v0.4.8).
// A full page section composed from Oeste components, inlined below so
// this file is self-contained. Copy-paste ready. Requires: React 18+,
// Tailwind with dark: variant, JSX transform.
// Requires Topanga tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/topanga/src/blocks.js
// Docs: https://oeste.hiddeninwest.com/topanga/#/blocks/logo-cloud

export function Separator({ orientation = "horizontal", decorative = true }) {
  if (orientation === "vertical") {
    return decorative
      ? <span aria-hidden="true" className="inline-block w-px self-stretch bg-[#1c1917]/10 dark:bg-[#f5f3ef]/10" />
      : <span role="separator" aria-orientation="vertical" className="inline-block w-px self-stretch bg-[#1c1917]/10 dark:bg-[#f5f3ef]/10" />;
  }
  return decorative
    ? <hr aria-hidden="true" className="my-4 border-0 border-t border-[#1c1917]/10 dark:border-[#f5f3ef]/10" />
    : <hr role="separator" aria-orientation="horizontal" className="my-4 border-0 border-t border-[#1c1917]/10 dark:border-[#f5f3ef]/10" />;
}

export function BlockLogoCloud() {
  const marks = ["Alder Studio", "Northlight", "Casa Verde", "Fern and Co", "Bluehour", "Atlas Ceramics"];
  return (
    <section aria-label="Studios using Fieldbook" className="bg-[#f6f4f1] px-6 py-12 text-[#1c1917] dark:bg-[#121110] dark:text-[#f5f3ef] lg:px-8">
      <div className="mx-auto max-w-[1200px]">
        <p className="text-sm text-[#706963] dark:text-[#9e968f]">Studios that keep their projects in Fieldbook</p>
        <div className="mt-6">
          <Separator />
        </div>
        <ul className="grid list-none grid-cols-2 gap-x-6 gap-y-4 p-0 py-8 sm:grid-cols-3 lg:flex lg:items-center lg:justify-between">
          {marks.map((m) => (
            <li key={m} className="text-base font-semibold text-[#706963] dark:text-[#9e968f]">{m}</li>
          ))}
        </ul>
        <Separator />
      </div>
    </section>
  );
}
